import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Header from "./component/Header";
import Sidebar from "./component/Sidebar";
import Leaflet from "./component/leaflet";
import LoginPage from "./pages/LoginPage/LoginPage";
import RegisterPage from "./pages/RegisterPage/RegisterPage";
import MyComplaintsPage from "./pages/MyComplaintsPage/MyComplaintsPage";
import CitizenProfile from "./pages/CitizenProfile/CitizenProfile";
import HelpSupport from "./pages/HelpSupport/HelpSupport";
import About from "./pages/About/About";
import HomePage from "./pages/Homepage/HomePage";

import "./styles/App.css";

function App() {
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const toggleSidebar = () => setSidebarOpen(!sidebarOpen);

  return (
    <Router>
      <Routes>

        {/* ── Fullscreen routes (no Header/Sidebar) ──────────────
            These pages manage their own layout entirely.         */}
        <Route path="/home"     element={<HomePage />} />
        <Route path="/login"    element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />

        {/* ── App routes (with Header + Sidebar) ─────────────────
            All these pages render inside the main app shell.     */}
        <Route path="/*" element={
          <div className="app">

            <Header toggleSidebar={toggleSidebar} />

            <div className="main">
              {sidebarOpen && <Sidebar />}

              <div className={`map ${sidebarOpen ? "map-with-sidebar" : ""}`}>
                <Routes>
                  <Route path="/"            element={<Leaflet />} />
                  <Route path="/map"         element={<Leaflet />} />
                  <Route path="/complaints"  element={<MyComplaintsPage />} />
                  <Route path="/citizen/:id" element={<CitizenProfile />} />
                  <Route path="/profile"     element={<CitizenProfile />} />
                  <Route path="/support"     element={<HelpSupport />} />
                  <Route path="/about"       element={<About />} />
                </Routes>
              </div>

            </div>
          </div>
        } />

      </Routes>
    </Router>
  );
}

export default App;
